"""Self-contained developer console for learning the agent pipeline."""
import json
from pathlib import Path

from .dashboard import save_html
from .realtime_dashboard import connection_summary


def write_agent_dashboard(path, report, connection=None):
    payload = {"report": report, "connection": connection_summary(connection)}
    data = json.dumps(payload, ensure_ascii=False, allow_nan=False)
    data = data.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return save_html(path, PAGE.replace("__PAYLOAD__", data))


